public static class TerminalOutputCheck{
static int checks;static void A(bool b,string s){checks++;if(!b)throw new Exception(s);}
static ItemValue V(int type){return new ItemValue(type){Meta=-1,Seed=17,TextureFullArray=new TextureFullArray(-23)};}
static byte[] Raw(ItemStack[] rows){using(var stream=new MemoryStream()){var w=MemoryPools.poolBinaryWriter.Value;var old=w.Encoding;try{w.Encoding=new UTF8Encoding(false,false);w.SetBaseStream(stream);w.Write((byte)rows.Length);foreach(var row in rows)row.Write(w);w.Flush();return stream.ToArray();}finally{w.Encoding=old;}}}
static void Bad(byte[] bytes,int count){int reads=ItemStack.Reads;ItemStack[] output;A(!RebirthStationTerminalContents.TryReadOutput(bytes,count,out output),"invalid output refused");A(output==null,"atomic null");A(reads==ItemStack.Reads,"preflight before native reads");}
public static int Main(){ItemClass.list[1]=new ItemClass{Name="output"};ItemClass.list[2]=new ItemClassModifier{Name="mod"};var rows=ItemStack.CreateArray(3);rows[0].count=4;rows[0].itemValue=V(1);rows[0].itemValue.modifications=new[]{V(2)};rows[0].itemValue.cosmeticMods=new[]{V(2)};rows[0].itemValue.SetMetadata("note","é🙂");rows[2].count=1;rows[2].itemValue=V(1);var bytes=Raw(rows);ItemStack[] result;A(RebirthStationTerminalContents.TryReadOutput(bytes,3,out result),"native output framing decoded");A(result.Length==3&&result[0].count==4&&result[1].count==0,"native counts preserved");A(RebirthNativeItemCodec.Encode(result[0].itemValue)==RebirthNativeItemCodec.Encode(rows[0].itemValue),"full root nested cosmetic texture and metadata preserved");A(!object.ReferenceEquals(result[0].itemValue,rows[0].itemValue),"detached native item");A(Raw(result).SequenceEqual(bytes),"whole native payload exact roundtrip");
for(int i=0;i<bytes.Length;i++)Bad(bytes.Take(i).ToArray(),3);Bad(bytes.Concat(new byte[]{0}).ToArray(),3);Bad(bytes,2);Bad(null,3);Bad(bytes,0);Bad(new byte[256*1024+1],3);var invalid=(byte[])bytes.Clone();invalid[3]=8;Bad(invalid,3);Console.WriteLine("PASS "+checks+" actual terminal output canonical native reader checks");return 0;}}